import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<String, Integer> allMemo = new HashMap<>();
    static Map<String, Integer> limitMemo = new HashMap<>();
    static int n = 0, m = 0;

    static int totalCombinations(int low, int high) {
        if (low == high) {
            return 1;
        }
        String key = low + "," + high;
        if (allMemo.containsKey(key)) {
            return allMemo.get(key);
        }
        int result = 0;
        result += totalCombinations(low + 1, high);
        result += totalCombinations(low, high - 1);
        for (int i = low + 1; i < high; i++) {
            result += totalCombinations(low, i - 1) * totalCombinations(i + 1, high);
        }
        allMemo.put(key, result);
        return result;
    }

    static int limitCombinations(int low, int high, int depth) {
        if (low == high) {
            return (depth < m) ? 1 : 0;
        }
        String key = low + "," + high + "," + depth;
        if (limitMemo.containsKey(key)) {
            return limitMemo.get(key);
        }
        int result = 0;
        result += limitCombinations(low + 1, high, depth + 1);
        result += limitCombinations(low, high - 1, depth + 1);
        for (int i = low + 1; i < high; i++) {
            result += limitCombinations(low, i - 1, depth + 1) * limitCombinations(i + 1, high, depth + 1);
        }
        limitMemo.put(key, result);
        return result;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        m = scanner.nextInt();
        int answer = totalCombinations(1, n) - limitCombinations(1, n, 1);
        System.out.println(answer);
        scanner.close();
    }
}
